<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {Image,RefreshCw,Download,X,LoaderCircle,Maximize2,AlertCircle,MousePointer2,ExternalLink,Minimize2,SlidersHorizontal,ChevronDown,ShieldCheck,ArrowLeft} from 'lucide-vue-next';
import BiLiveViewer from './BiLiveViewer.vue';
import type {PreviewDevice} from '../lib/responsive-preview';
import {appUrl} from '../lib/urls';
import {choosePreview,dashboardPreviews,projectPreviews,shouldFollowLivePreview} from '../lib/project-previews';
type Item=Record<string,any>;
const props=defineProps<{project:Item;artifacts:Item[];expanded?:boolean;pendingReviews?:number;visible?:boolean;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{close:[];review:[];expand:[expanded:boolean];inspect:[artifact:Item];generated:[artifact:Item]}>();
const device=ref<PreviewDevice>('auto');const mode=ref<'interactive'|'image'>('interactive');const interactiveAvailable=ref(false);const nativeUrl=ref('');const liveVersion=ref(0);const requestedDashboard=ref<string|null>(new URLSearchParams(window.location.search).get('dashboard'));
function openInteractive(id?:string|null){mode.value='interactive';if(id){requestedDashboard.value=id;if(dashboards.value.some(item=>String(item.id)===id)){dashboard.value=id;choseDashboard.value=true;}}liveVersion.value++;}
defineExpose({openInteractive});
const liveContext=computed(()=>({projectId:String(props.project.id),resource:props.project.source_ref??null,revision:props.project.preview_revision??null}));
const displayedLiveContext=ref(liveContext.value);const legacyRefreshPending=ref(false);
function viewerStarted(){displayedLiveContext.value=liveContext.value;legacyRefreshPending.value=false;}
const sourceAvailable=computed(()=>/^app:[1-9][0-9]*$/.test(props.project.source_ref??''));
const allChoices=computed(()=>projectPreviews(props.artifacts,props.project.id,props.project.source_ref));
const dashboards=ref<Item[]>([]);const dashboard=ref('');const contextLoading=ref(false);const contextError=ref('');const contextReady=ref(false);const listAvailable=ref(true);const choseDashboard=ref(false);
const choices=computed(()=>dashboardPreviews(allChoices.value,dashboard.value||null,dashboards.value[0]?.id?String(dashboards.value[0].id):null));
const follow=ref(true);const selectedId=ref<string|null>(null);const selected=computed(()=>choosePreview(choices.value,selectedId.value,follow.value));
const canRender=computed(()=>sourceAvailable.value&&contextReady.value&&!contextLoading.value&&(dashboards.value.length>0||!listAvailable.value));
const image=ref('');const loading=ref(false);const rendering=ref(false);const error=ref('');let version=0;let contextVersion=0;let disposed=false;
function date(value:string){const time=new Date(value);return Number.isNaN(time.getTime())?'Data não informada':time.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});}
function clear(){if(image.value)URL.revokeObjectURL(image.value);image.value='';}
async function loadContext(reloadLive=false){const current=++contextVersion;contextError.value='';if(!sourceAvailable.value){contextReady.value=false;contextLoading.value=false;return;}contextLoading.value=true;try{const result=await props.request(`/projects/${props.project.id}/preview-context`);if(current!==contextVersion)return;if(!Array.isArray(result.dashboards))throw new Error('A lista de dashboards não retornou um formato reconhecido.');dashboards.value=result.dashboards;interactiveAvailable.value=result.interactive_available===true;nativeUrl.value=result.native_app_url??'';if(!interactiveAvailable.value)mode.value='image';if(requestedDashboard.value&&dashboards.value.some(item=>String(item.id)===requestedDashboard.value)){dashboard.value=requestedDashboard.value;choseDashboard.value=true;}listAvailable.value=result.dashboards_available!==false;const latest=String(allChoices.value[0]?.metadata?.dashboard_id??'');if(!(choseDashboard.value&&dashboards.value.some(item=>String(item.id)===dashboard.value)))dashboard.value=dashboards.value.some(item=>String(item.id)===latest)?latest:String(dashboards.value[0]?.id??'');if(reloadLive&&follow.value&&mode.value==='interactive')liveVersion.value++;contextReady.value=true;}catch(e){if(current===contextVersion){contextReady.value=false;contextError.value=(e as Error).message;}}finally{if(current===contextVersion)contextLoading.value=false;}}
async function load(){const current=++version;clear();error.value='';if(mode.value!=='image'||!selected.value){loading.value=false;return;}const artifact=selected.value;loading.value=true;try{const response=await fetch(appUrl('/api/artifacts/'+encodeURIComponent(artifact.id)+'/download'),{credentials:'same-origin'});if(response.status===401){window.location.assign(appUrl('/login'));return;}if(!response.ok)throw new Error('Não foi possível abrir esta prévia. Confira sua sessão e tente novamente.');const blob=await response.blob();if(blob.type!=='image/png')throw new Error('O arquivo não retornou uma prévia PNG válida.');if(current===version)image.value=URL.createObjectURL(blob);}catch(e){if(current===version)error.value=(e as Error).message;}finally{if(current===version)loading.value=false;}}
async function generate(){if(!canRender.value||rendering.value)return;rendering.value=true;error.value='';try{const result=await props.request(`/projects/${props.project.id}/preview`,'POST',dashboard.value?{dashboard:Number(dashboard.value)}:{});if(disposed)return;follow.value=true;emit('generated',result.artifact);}catch(e){if(!disposed)error.value=(e as Error).message;}finally{rendering.value=false;}}
function toggleFollow(event:Event){const enabled=(event.target as HTMLInputElement).checked;if(!enabled)selectedId.value=selected.value?.id??null;follow.value=enabled;if(enabled&&props.visible!==false&&mode.value==='interactive'&&(legacyRefreshPending.value||shouldFollowLivePreview(displayedLiveContext.value,liveContext.value,true,mode.value)))loadContext(true);}
function select(event:Event){selectedId.value=(event.target as HTMLSelectElement).value;choseDashboard.value=true;follow.value=false;}
function selectDashboard(event:Event){dashboard.value=(event.target as HTMLSelectElement).value;choseDashboard.value=true;selectedId.value=null;follow.value=true;}
watch([()=>selected.value?.id,()=>mode.value],load,{immediate:true});
watch([()=>props.project.id,()=>props.project.source_ref],()=>{nativeUrl.value='';interactiveAvailable.value=false;dashboards.value=[];dashboard.value='';choseDashboard.value=false;loadContext();},{immediate:true});
watch(()=>allChoices.value[0]?.id,()=>{if(!props.project.preview_revision){legacyRefreshPending.value=true;if(follow.value&&mode.value==='interactive'&&props.visible!==false)liveVersion.value++;}const latest=String(allChoices.value[0]?.metadata?.dashboard_id??'');if(!latest||!sourceAvailable.value)return;if(!dashboards.value.some(item=>String(item.id)===latest)){loadContext();return;}if(!choseDashboard.value&&follow.value)dashboard.value=latest;});
watch(liveContext,(after,before)=>{if(shouldFollowLivePreview(before,after,follow.value,mode.value,props.visible!==false))loadContext(true);});
watch(()=>props.visible,visible=>{if(visible!==false&&follow.value&&mode.value==='interactive'&&(legacyRefreshPending.value||shouldFollowLivePreview(displayedLiveContext.value,liveContext.value,true,mode.value)))loadContext(true);});
watch(mode,(after,before)=>{if(after==='interactive'&&before==='image'&&sourceAvailable.value){contextReady.value=false;loadContext();}});
onUnmounted(()=>{disposed=true;version++;contextVersion++;clear();});
</script>
<template>
 <aside data-tour="chat-preview" class="project-preview-pane" :class="{'is-interactive':mode==='interactive','is-expanded':expanded}" aria-label="Acompanhamento visual do dashboard">
  <header class="project-preview-header">
   <div><Image :size="17"/><strong>Prévia do dashboard</strong></div>
   <div class="project-preview-header-actions">
    <a v-if="nativeUrl" :href="nativeUrl" target="_blank" rel="noopener noreferrer" class="preview-native-link" aria-label="Abrir dashboard no BI em outra aba"><ExternalLink :size="14"/><span>Abrir no BI</span></a>
    <button type="button" class="preview-expand-button" data-tour="chat-preview-expand" :aria-pressed="!!expanded" :aria-label="expanded?'Restaurar conversa e prévia lado a lado':'Ampliar área do dashboard'" @click="emit('expand',!expanded)"><Minimize2 v-if="expanded" :size="15"/><Maximize2 v-else :size="15"/><span>{{expanded?'Ver conversa':'Ampliar'}}</span></button>
    <button type="button" class="preview-close-button" aria-label="Fechar acompanhamento visual" @click="emit('close')"><X :size="17"/><span>Conversa</span></button>
   </div>
  </header>
  <div v-if="pendingReviews" class="preview-review-notice" role="status" aria-live="polite" data-tour="chat-preview-review">
   <ShieldCheck :size="21"/><div><strong>Autorização necessária</strong><p>{{pendingReviews===1?'A IA aguarda sua decisão.':pendingReviews+' solicitações aguardam sua decisão.'}}</p></div><button type="button" @click="emit('review')">Revisar na conversa<ArrowLeft :size="14"/></button>
  </div>
  <div class="project-preview-toolbar">
   <div class="project-preview-modes" role="group" aria-label="Tipo de prévia">
    <button type="button" :aria-pressed="mode==='interactive'" :disabled="!interactiveAvailable||!contextReady" @click="mode='interactive'"><MousePointer2 :size="14"/>Interativa</button>
    <button type="button" :aria-pressed="mode==='image'" @click="mode='image'"><Image :size="14"/>Imagem</button>
   </div>
   <label v-if="dashboards.length" class="project-preview-dashboard"><span class="sr-only">Dashboard da prévia</span><select :value="dashboard" aria-label="Dashboard da prévia" :disabled="contextLoading||rendering" @change="selectDashboard"><option v-for="item in dashboards" :key="item.id" :value="String(item.id)">{{item.name}}</option></select></label>
   <details class="project-preview-options">
    <summary data-tour="chat-preview-options" :aria-label="follow?'Opções da prévia':'Opções da prévia, acompanhamento pausado'"><SlidersHorizontal :size="15"/><span>Opções</span><small v-if="!follow" class="preview-paused-label">Pausado</small><ChevronDown :size="12"/></summary>
    <div class="project-preview-options-content">
     <strong>Opções da prévia</strong>
     <label class="preview-follow"><input data-tour="chat-preview-follow" :checked="follow" type="checkbox" @change="toggleFollow"> Acompanhar alterações</label>
     <p>{{mode==='interactive'?'Explore filtros e gráficos. Alterações concluídas no projeto atualizam o painel quando o acompanhamento está ativo, mesmo sem gerar uma imagem.':'A imagem registra uma versão renderizada. Abra a prévia interativa para explorar filtros e gráficos.'}}</p>
     <button type="button" class="secondary-button" :disabled="contextLoading" @click="loadContext()"><RefreshCw :size="14" :class="{spin:contextLoading}"/>Atualizar lista de dashboards</button>
     <button v-if="mode==='image'" type="button" class="secondary-button" :disabled="rendering||!canRender" @click="generate"><LoaderCircle v-if="rendering" :size="14" class="spin"/><RefreshCw v-else :size="14"/>{{rendering?'Gerando imagem…':'Gerar nova imagem'}}</button>
     <p class="preview-permission-note">A visualização usa as permissões da sua conta G-Analise BI.</p>
    </div>
   </details>
  </div>
  <p v-if="contextError" class="form-error" role="alert">{{contextError}}</p>
  <div v-if="contextLoading&&!contextReady" class="project-preview-loading" role="status"><LoaderCircle :size="23" class="spin"/><span>Abrindo seu dashboard…</span></div>
  <div v-if="!sourceAvailable&&mode==='interactive'" class="project-preview-empty"><Image :size="34"/><h3>Seu dashboard vai aparecer aqui</h3><p>Descreva na conversa o que deseja criar. Assim que a IA preparar a primeira versão, você poderá acompanhá-la neste espaço.</p></div>
  <BiLiveViewer v-if="mode==='interactive'&&interactiveAvailable&&contextReady" :key="project.source_ref+':'+dashboard+':'+liveVersion" compact device-controls :active="visible!==false" v-model:device="device" :tenant="String(project.tenant_id)" :app-id="project.source_ref.slice(4)" :dashboard="dashboard||undefined" :request="request" @started="viewerStarted" @fallback="mode='image'"/>
  <div v-if="mode==='image'" class="project-preview-image-body">
   <div v-if="choices.length>1" class="project-preview-version"><label for="preview-image-version">Versão da imagem</label><select id="preview-image-version" :value="selected?.id" aria-label="Versão da prévia" @change="select"><option v-for="artifact in choices" :key="artifact.id" :value="artifact.id">{{date(artifact.metadata?.generated_at??artifact.created_at)}}</option></select></div>
   <button v-if="selected&&choices[0]?.id!==selected.id" class="preview-latest" @click="follow=true">Ver a prévia mais recente</button>
   <div v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}<button v-if="selected" class="text-button" @click="load">Tentar abrir novamente</button></div>
   <div v-if="loading" class="project-preview-loading" role="status"><LoaderCircle :size="22" class="spin"/>Carregando imagem…</div>
   <div v-else-if="image&&selected" class="project-preview-canvas"><button class="project-preview-enlarge" aria-label="Ampliar imagem do dashboard" @click="emit('inspect',selected)"><img :src="image" :alt="'Prévia real de '+project.name"></button></div>
   <div v-else-if="!selected&&!loading" class="project-preview-empty"><Image :size="34"/><h3>Acompanhe o dashboard aqui</h3><p>{{sourceAvailable?'Gere uma imagem do dashboard selecionado ou use a prévia interativa.':'A primeira prévia aparecerá quando uma aplicação for criada neste projeto.'}}</p><button v-if="sourceAvailable" class="secondary-button" :disabled="rendering||!canRender" @click="generate"><RefreshCw :size="14"/>{{rendering?'Gerando imagem…':'Gerar imagem'}}</button></div>
   <footer v-if="selected"><span>{{date(selected.metadata?.generated_at??selected.created_at)}} · Brasília</span><div><button class="secondary-button" :disabled="!image" @click="emit('inspect',selected)"><Maximize2 :size="14"/>Ampliar imagem</button><a class="secondary-button" :href="appUrl('/api/artifacts/'+selected.id+'/download')"><Download :size="14"/>Baixar</a></div><p>Para análise visual com IA, abra a imagem e autorize o envio para a conversa.</p></footer>
  </div>
 </aside>
</template>

